begin;
set local timezone='America/Bahia';
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values('b11a2000-0000-4000-8000-000000000001','authenticated','authenticated','quality-canonical@example.test','',now(),'{}','{"name":"Quality Canonical QA","company_name":"Quality Canonical QA"}',now(),now());
select set_config('request.jwt.claims','{"sub":"b11a2000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('qx.company',private.current_company_id(),true);
select set_config('qx.manager',(select id from public.profiles where auth_user_id=auth.uid()),true);
insert into public.customers(id,company_id,name,document) values('jx-customer',private.current_company_id(),'Cliente canônico QA','');
insert into public.suppliers(id,company_id,name) values('jx-supplier',private.current_company_id(),'Fornecedor canônico QA');
insert into public.products(id,company_id,name,pricing_type,base_cost,sales_price,stock_controlled,current_stock,min_stock) values('jx-material',private.current_company_id(),'Material canônico QA','unidade',2,5,true,10,0);
insert into public.orders(id,company_id,customer_id,customer_name,number,status,total_amount,paid_amount,payment_status,shipping_cost,deadline,notes) values('jx-order',private.current_company_id(),'jx-customer','Cliente canônico QA','PED-11JX','producao',100,0,'pendente',0,now()+interval '2 days','QA');
insert into public.order_items(id,order_id,product_id,product_name,quantity,unit_price,total_price,details) values('jx-item','jx-order','jx-material','Material canônico QA',10,10,100,'{}');
insert into public.production_queue(id,company_id,order_id,order_number,order_item_id,product_name,quantity,status) values('jx-queue',private.current_company_id(),'jx-order','PED-11JX','jx-item','Material canônico QA',10,'fila');
create function pg_temp.qx(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.quality_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at,'cost_version',public.quality_source(current_date,current_date,id)#>>'{cases,0,cost_version}') from public.quality_nonconformities where id=current_setting('qx.id')::uuid)||patch)$$;
create function pg_temp.fx(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.field_service_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at) from public.field_services where id=current_setting('qx.service')::uuid)||patch)$$;
create function pg_temp.tx(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.composite_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at) from public.outsourcing_orders where id=current_setting('qx.ot')::uuid)||patch)$$;
create function pg_temp.qx_create() returns jsonb language sql as $$select public.quality_command(gen_random_uuid(),'create',jsonb_build_object('source_type','field_service','source_id',current_setting('qx.original'),'source_updated_at',public.quality_origins('field_service','',0,current_setting('qx.original'))#>>'{origin,version}','description','Divergência sintética após instalação','category','installation','severity','medium','affected_quantity',2,'assigned_profile_id',current_setting('qx.manager'),'cost_applicable',true))$$;
create function pg_temp.qx_plan(mode text) returns jsonb language sql as $$select pg_temp.qx('action_define',jsonb_build_object('kind','rework','execution_mode',mode,'quantity',2,'assigned_profile_id',current_setting('qx.manager'),'supplier_id',case when mode='outsourced' then 'jx-supplier' end,'due_date',current_date+3,'notes','Correção sintética do lote afetado'))$$;
grant execute on function pg_temp.qx(text,jsonb),pg_temp.fx(text,jsonb),pg_temp.tx(text,jsonb),pg_temp.qx_create(),pg_temp.qx_plan(text) to authenticated;
set local role authenticated;
select set_config('qx.ot',public.composite_command(gen_random_uuid(),'ot_save',jsonb_build_object('order_id','jx-order','order_item_id','jx-item','supplier_id','jx-supplier','title','OT canônica fora das ações da NC','quantity',2,'unit','unidade','due_date',current_date+2,'unit_cost',5,'freight',0))->>'id',true);
select set_config('qx.external_ot',current_setting('qx.ot'),true);
select pg_temp.tx('ot_transition','{"status":"issued"}');select pg_temp.tx('ot_transition','{"status":"confirmed"}');select pg_temp.tx('ot_dispatch','{"materials_sent":false,"notes":"Serviço sem material enviado"}');select pg_temp.tx('ot_receive',jsonb_build_object('quantity',2,'received_date',current_date,'quality','accepted'));select pg_temp.tx('ot_cost','{"actual_cost":10,"reason":"Apuração canônica fora da NC"}');
reset role;
update public.production_queue set status='concluido' where id='jx-queue';
set local role authenticated;
select set_config('qx.service',public.field_service_command(gen_random_uuid(),'save',jsonb_build_object('order_id','jx-order','order_item_id','jx-item','service_type','installation','title','Instalação original QA','assigned_profile_id',current_setting('qx.manager'),'address','{"street":"Rua QA","number":"10","city":"Recife","state":"PE"}'::jsonb,'checklist','[]'::jsonb))->>'id',true);
select pg_temp.fx('schedule',jsonb_build_object('start',clock_timestamp()+interval '1 day','end',clock_timestamp()+interval '1 day 1 hour'));
select pg_temp.fx('transition','{"status":"traveling"}');select pg_temp.fx('transition','{"status":"on_site"}');select pg_temp.fx('transition','{"status":"running"}');select pg_temp.fx('complete','{"note":"Instalação original QA concluída"}');
select set_config('qx.original',current_setting('qx.service'),true);
reset role;
update public.production_queue set status='concluido' where id='jx-queue';
update public.orders set status='entregue' where id='jx-order';
set local role authenticated;
select set_config('qx.id',pg_temp.qx_create()->>'id',true);
select pg_temp.qx('analyze','{"root_cause":"Falha de instalação constatada","analysis":"Conferência sintética da origem"}');
select lives_ok($$select pg_temp.qx_plan('outsourced')$$,'plan canonical outsourced rework after delivery');
select lives_ok($$select pg_temp.qx('action_start',jsonb_build_object('production_updated_at',(select updated_at from public.production_queue where id='jx-queue'),'unit','unidade','unit_cost',4,'freight',3))$$,'quality scope extends existing OT engine without changing delivered Order');
select set_config('qx.ot',(select outsourcing_id::text from public.quality_actions where id=(select action_id from public.quality_nonconformities where id=current_setting('qx.id')::uuid)),true);
select is((select status from public.orders where id='jx-order'),'entregue','commercial delivery remains untouched');
select is((select quantity from public.production_queue where id='jx-queue'),2::numeric,'same queue carries partial corrective quantity');
select is((select current_stock from public.products where id='jx-material'),10::numeric,'starting OT never duplicates material consumption');
select pg_temp.tx('ot_transition','{"status":"issued"}');select pg_temp.tx('ot_transition','{"status":"confirmed"}');select pg_temp.tx('ot_dispatch','{"materials_sent":false,"notes":"Serviço QA sem envio físico"}');
select set_config('qx.receipt',pg_temp.tx('ot_receive',jsonb_build_object('quantity',2,'received_date',current_date,'quality','accepted','notes','Conferência sintética'))->>'receipt_id',true);
select pg_temp.tx('ot_cost','{"actual_cost":10,"reason":"Apuração efetiva sintética QA"}');
select lives_ok($$select pg_temp.qx('cost_save',jsonb_build_object('kind','outsourcing','description','OT corretiva canônica QA','planned',11,'outsourcing_id',current_setting('qx.ot')))$$,'bind existing OT cost instead of another payable');
select is((public.quality_source(current_date,current_date,current_setting('qx.id')::uuid)#>>array['summaries',current_setting('qx.id'),'actual'])::numeric,13::numeric,'OT actual includes its canonical freight once');
select throws_like($$select pg_temp.qx('cost_export',jsonb_build_object('cost_id',(select id from public.quality_costs where nc_id=current_setting('qx.id')::uuid)))$$,'%OT e retorno usam%','OT reference cannot create a duplicate financial obligation');
select pg_temp.qx('action_finish','{"result":"Lote corretivo recebido e conferido"}');
select pg_temp.qx('reinspect','{"result":"approved","notes":"Conferência aprovada antes da reversão"}');
select set_config('qx.old_revision',public.quality_source(current_date,current_date,current_setting('qx.id')::uuid)#>>'{cases,0,cost_version}',true);
select pg_temp.tx('ot_receipt_reverse',jsonb_build_object('receipt_id',current_setting('qx.receipt'),'reason','Reversão sintética da comprovação'));
select throws_like($$select pg_temp.qx('close',jsonb_build_object('cost_version',current_setting('qx.old_revision')))$$,'%apuração mudaram%','canonical OT change invalidates old closure revision');
select throws_like($$select pg_temp.qx('close')$$,'%comprovação da OT foi revertida%','old approved inspection does not validate reversed receipt');
select lives_ok($$select pg_temp.qx('action_invalidate','{"reason":"Comprovação foi revertida após inspeção"}')$$,'explicit invalidation preserves old result and inspection');
select is((select count(*) from public.quality_reinspections where nc_id=current_setting('qx.id')::uuid and result='approved'),1::bigint,'approved inspection is not erased or rewritten');

-- A second case uses a distinct canonical OT, then a canonical field return.
select set_config('qx.id',pg_temp.qx_create()->>'id',true);
select pg_temp.qx('analyze','{"root_cause":"Falha de instalação constatada","analysis":"Conferência sintética do local"}');
select pg_temp.qx_plan('outsourced');
select pg_temp.qx('action_start',jsonb_build_object('production_updated_at',(select updated_at from public.production_queue where id='jx-queue'),'unit_cost',2,'freight',0));
select set_config('qx.ot',(select outsourcing_id::text from public.quality_actions where id=(select action_id from public.quality_nonconformities where id=current_setting('qx.id')::uuid)),true);
select pg_temp.tx('ot_transition','{"status":"issued"}');select pg_temp.tx('ot_transition','{"status":"confirmed"}');select pg_temp.tx('ot_dispatch','{"materials_sent":false,"notes":"Correção sintética sem envio"}');select pg_temp.tx('ot_receive',jsonb_build_object('quantity',2,'received_date',current_date,'quality','accepted'));select pg_temp.tx('ot_cost','{"actual_cost":10,"reason":"Apuração efetiva sintética QA"}');
select pg_temp.qx('action_finish','{"result":"Peças corrigidas antes da reinstalação"}');select pg_temp.qx('reinspect','{"result":"rejected","notes":"Peças corretas; local exige retorno técnico"}');
select pg_temp.qx_plan('field');select pg_temp.qx('action_start');
select lives_ok($$select pg_temp.qx('field_return')$$,'create return through canonical field service command');
select set_config('qx.service',(select return_service_id::text from public.quality_actions where id=(select action_id from public.quality_nonconformities where id=current_setting('qx.id')::uuid)),true);
select throws_like($$select pg_temp.qx('field_return')$$,'%já possui retorno%','new nonce never duplicates linked field return');
select is((select count(*) from public.field_services where company_id=current_setting('qx.company')),2::bigint,'one original service and one canonical return');
select throws_like($$select pg_temp.qx('material_consume','{"product_id":"jx-material","quantity":1}')$$,'%somente em Serviços Externos%','field materials have one canonical movement interface');
select set_config('qx.ot',current_setting('qx.external_ot'),true);
select pg_temp.fx('cost_save',jsonb_build_object('kind','third_party','description','Terceiro da OT QA','planned',10,'actual',5,'outsourcing_id',current_setting('qx.ot')));
select set_config('qx.first_cost',(select id::text from public.field_service_costs where service_id=current_setting('qx.service')::uuid),true);
select pg_temp.fx('cost_save',jsonb_build_object('kind','third_party','description','Vínculo OT duplicado QA','planned',10,'actual',5,'outsourcing_id',current_setting('qx.ot')));
select set_config('qx.duplicate_cost',(select id::text from public.field_service_costs where service_id=current_setting('qx.service')::uuid and id<>current_setting('qx.first_cost')::uuid),true);
select throws_like($$select pg_temp.qx('cost_save',jsonb_build_object('kind','field_service','description','Retorno sem dupla apropriação','planned',14,'service_id',current_setting('qx.service')))$$,'%OT já apropriada%','duplicate OT inside one aggregated return is rejected');
select pg_temp.fx('cost_save',jsonb_build_object('cost_id',current_setting('qx.duplicate_cost'),'kind','expense','description','Duplicidade corrigida sem gasto','planned',0,'actual',0,'outsourcing_id',null));
select pg_temp.fx('cost_save','{"kind":"travel","description":"Deslocamento adicional QA","planned":2,"actual":2}');
select lives_ok($$select pg_temp.qx('cost_save',jsonb_build_object('kind','field_service','description','Retorno canônico por execução','planned',14,'service_id',current_setting('qx.service')))$$,'one OT origin can now be bound once inside return');
select is((public.quality_source(current_date,current_date,current_setting('qx.id')::uuid)#>>array['summaries',current_setting('qx.id'),'actual'])::numeric,12::numeric,'return uses canonical OT total, not duplicate/manual third-party amount');
select throws_like($$select pg_temp.fx('cost_save',jsonb_build_object('kind','third_party','description','Outra tentativa duplicada QA','planned',10,'actual',10,'outsourcing_id',current_setting('qx.ot')))$$,'%OT já apropriada%','later field writes cannot introduce a second claimed OT');
select pg_temp.fx('schedule',jsonb_build_object('start',clock_timestamp()+interval '1 day','end',clock_timestamp()+interval '1 day 1 hour'));select pg_temp.fx('transition','{"status":"traveling"}');select pg_temp.fx('transition','{"status":"on_site"}');select pg_temp.fx('transition','{"status":"running"}');select pg_temp.fx('checklist','{"item":"retorno","done":true}');
select pg_temp.fx('material_add','{"product_id":"jx-material","quantity":1}');
select set_config('qx.material',(select id::text from public.field_service_materials where service_id=current_setting('qx.service')::uuid),true);
select pg_temp.fx('material_take',jsonb_build_object('material_id',current_setting('qx.material'),'quantity',1));select pg_temp.fx('material_settle',jsonb_build_object('material_id',current_setting('qx.material'),'consumed',1,'returned',0));
select is((select current_stock from public.products where id='jx-material'),9::numeric,'one field take is the only stock debit');
select pg_temp.fx('complete','{"note":"Retorno sintético conferido"}');
select pg_temp.fx('reopen','{"reason":"Outra execução técnica após este retorno"}');
select lives_ok($$select pg_temp.qx('action_finish','{"result":"Execução um concluída e preservada no serviço"}')$$,'linked historical completion remains valid after another service run starts');
select pg_temp.qx('reinspect','{"result":"approved","notes":"Duas unidades reinspecionadas no local"}');
select set_config('qx.old_revision',public.quality_source(current_date,current_date,current_setting('qx.id')::uuid)#>>'{cases,0,cost_version}',true);
select pg_temp.tx('ot_cost','{"actual_cost":12,"reason":"Revisão da OT transitiva do retorno"}');
select throws_like($$select pg_temp.qx('close',jsonb_build_object('cost_version',current_setting('qx.old_revision')))$$,'%apuração mudaram%','transitive return OT change invalidates old closure revision');
select pg_temp.tx('ot_cost','{"actual_cost":10,"reason":"Conciliação da OT transitiva QA"}');
select lives_ok($$select pg_temp.qx('close')$$,'close with canonical return, material and OT costs');
reset role;
select is((select (cost_snapshot->>'actual')::numeric from public.quality_closures where nc_id=current_setting('qx.id')::uuid),14::numeric,'closure freezes OT 10 plus travel 2 plus physical material 2');
set local role authenticated;
select pg_temp.fx('material_reverse',jsonb_build_object('material_id',current_setting('qx.material'),'reason','Retorno físico da fixture QA'));
select is((public.quality_source(current_date,current_date,current_setting('qx.id')::uuid)#>>array['summaries',current_setting('qx.id'),'actual'])::numeric,14::numeric,'closed total remains frozen after canonical material inverse');
select is((select current_stock from public.products where id='jx-material'),10::numeric,'inverse restores canonical stock');
reset role;
select * from finish();rollback;
